import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  Box,
  Typography,
  TextField,
  Button,
  Card,
  CardContent,
  MenuItem,
  Modal
} from "@mui/material";
import { supabase } from "../supabase";

const SignUpPage = () => {
  const [name, setName] = useState("");
  const [dob, setDob] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("student");
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const navigate = useNavigate();

  const handleSignUp = async (e) => {
    e.preventDefault();
    setError(null);

    if (!name || !dob || !email || !password || !role) {
      setError("All fields are required!");
      return;
    }

    setLoading(true);
    try {
      const redirectTo = `${window.location.origin}/verify`;

      const { error: signUpError } = await supabase.auth.signUp({
        email,
        password,
        options: {
          emailRedirectTo: redirectTo,
          data: { name, dob, role },
        },
      });

      if (signUpError) throw signUpError;

      setShowModal(true);
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    navigate("/signin");
  };

  return (
    <>
      <Box sx={{ width: "100vw", height: "100vh", display: "flex", overflow: "hidden" }}>
        {/* Left Section */}
        <Box
          sx={{
            width: "50%",
            backgroundColor: "#8E2839",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            color: "white",
            padding: "40px",
            position: "relative",
            "&::before": {
              content: '""',
              position: "absolute",
              top: 0,
              right: "-50px",
              width: "100px",
              height: "100%",
              backgroundColor: "#FFF",
              borderRadius: "50%",
            },
          }}
        >
          <Typography variant="h4" fontWeight="bold" mb={2}>
            Welcome Back!
          </Typography>
          <Typography textAlign="center" mb={4} fontSize="1.125rem">
            To keep connected with us, please login with your personal info
          </Typography>
          <Link to="/signin">
            <Button
              variant="outlined"
              sx={{
                color: "white",
                borderColor: "white",
                padding: "10px 32px",
                borderRadius: "999px",
                fontSize: "1rem",
                transition: "0.3s",
                "&:hover": {
                  backgroundColor: "white",
                  color: "#8E2839",
                },
              }}
            >
              SIGN IN
            </Button>
          </Link>
        </Box>

        {/* Right Section - Sign Up Form */}
        <Box
          sx={{
            width: "50%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            backgroundColor: "#FFF",
          }}
        >
          <Card sx={{ width: "90%", maxWidth: 420, padding: 3, boxShadow: 3, borderRadius: 3 }}>
            <CardContent>
              <Typography variant="h4" fontWeight="bold" color="#8E2839" mb={1}>
                Create Account
              </Typography>
              <Typography color="gray" mb={3}>
                Sign up to enjoy the feature of EXAM
              </Typography>

              <form onSubmit={handleSignUp}>
                <TextField
                  fullWidth
                  label="Full Name"
                  variant="outlined"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  required
                  disabled={showModal}
                  sx={{ mb: 2, borderRadius: "8px", "& .MuiOutlinedInput-root": { borderRadius: "8px" } }}
                />

                <TextField
                  fullWidth
                  type="date"
                  label="Date of Birth"
                  value={dob}
                  onChange={(e) => setDob(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  required
                  disabled={showModal}
                  sx={{
                    mb: 2,
                    borderRadius: "8px",
                    "& .MuiOutlinedInput-root": { borderRadius: "8px" },
                    "& input::-webkit-calendar-picker-indicator": {
                      filter: "invert(0.5)",
                      cursor: "pointer",
                    },
                  }}
                />

                <TextField
                  fullWidth
                  label="Email"
                  variant="outlined"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  disabled={showModal}
                  sx={{ mb: 2, borderRadius: "8px", "& .MuiOutlinedInput-root": { borderRadius: "8px" } }}
                />

                <TextField
                  fullWidth
                  label="Password"
                  type="password"
                  variant="outlined"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  disabled={showModal}
                  sx={{ mb: 2, borderRadius: "8px", "& .MuiOutlinedInput-root": { borderRadius: "8px" } }}
                />

                <TextField
                  select
                  fullWidth
                  label="Are you a Student or Professor?"
                  value={role}
                  onChange={(e) => setRole(e.target.value)}
                  required
                  disabled={showModal}
                  sx={{ mb: 2, borderRadius: "8px", "& .MuiOutlinedInput-root": { borderRadius: "8px" } }}
                >
                  <MenuItem value="student">Student</MenuItem>
                  <MenuItem value="professor">Professor</MenuItem>
                </TextField>

                {error && (
                  <Typography color="red" fontSize="0.875rem" mb={2}>
                    {error}
                  </Typography>
                )}

                {!showModal && (
                  <Button
                    type="submit"
                    fullWidth
                    disabled={loading}
                    sx={{
                      backgroundColor: loading ? "#aaa" : "#8E2839",
                      color: "white",
                      padding: "12px",
                      borderRadius: "999px",
                      fontSize: "1.125rem",
                      transition: "0.3s",
                      "&:hover": {
                        backgroundColor: loading ? "#aaa" : "#7A2231",
                      },
                    }}
                  >
                    {loading ? "Creating Account..." : "Create Account"}
                  </Button>
                )}
              </form>
            </CardContent>
          </Card>
        </Box>
      </Box>

      {/* ✅ Modal Window */}
      <Modal open={showModal} onClose={handleCloseModal}>
        <Box
          sx={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: 360,
            bgcolor: "background.paper",
            borderRadius: 2,
            boxShadow: 24,
            p: 4,
            textAlign: "center",
          }}
        >
          <Typography variant="h6" mb={2} color="#8E2839">
            🎉 You're Almost There!
          </Typography>
          <Typography fontSize="0.95rem" mb={3}>
            We've sent a confirmation link to your email. <br />
            Please verify it to activate your account.
          </Typography>
          <Button
            variant="contained"
            sx={{ backgroundColor: "#8E2839" }}
            onClick={handleCloseModal}
          >
            Go to Sign In
          </Button>
        </Box>
      </Modal>
    </>
  );
};

export default SignUpPage;
